"use client";

import { useState } from "react";
import Image from "next/image";
import { 
  Building2, Home, Trees, Waves, MapPin, BedDouble, Bath, Car, Ruler,
  Heart, Phone, Mail, Share2, Printer, X, ChevronLeft, ChevronRight
} from "lucide-react";
import Link from "next/link";

interface PropertyCardProps {
  property: {
    id: string;
    title: string;
    description?: string;
    property_type: string;
    transaction_type: string;
    price: number;
    bedrooms?: number;
    bathrooms?: number;
    parking_spaces?: number;
    total_area?: number;
    city: string;
    state: string;
    country?: string;
    slug: string;
    featured?: boolean;
    property_photos?: { url: string; is_cover: boolean }[];
  };
  onFavorite?: () => void;
  isFavorited?: boolean;
  showFazerProposta?: boolean;
  onFazerProposta?: () => void;
}

const PROPERTY_TYPE_ICONS: Record<string, React.ComponentType<{ className?: string }>> = {
  apartment: Building2,
  house: Home,
  chacara: Trees,
  sitio: Trees,
  fazenda: Trees,
  rancho: Waves,
  commercial: Building2,
  land: MapPin,
};

export default function PropertyCard({
  property,
  onFavorite,
  isFavorited = false,
  showFazerProposta = false,
  onFazerProposta,
}: PropertyCardProps) {
  const IconComponent = PROPERTY_TYPE_ICONS[property.property_type] || Building2;

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
    }).format(price);
  };

  const getCoverPhoto = (photos: Array<{ url?: string; is_cover?: boolean }>) => {
    const cover = photos?.find(p => p.is_cover);
    return cover?.url || photos?.[0]?.url || '/images/placeholder-property.jpg';
  };

  const getPropertyTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      apartment: 'Apartment',
      house: 'House',
      chacara: 'Ch├ícara',
      sitio: 'S├¡tio',
      fazenda: 'Fazenda',
      rancho: 'Rancho',
      commercial: 'Commercial',
      land: 'Land',
    };
    return labels[type] || type;
  };

  return (
    <div className="group bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] hover:border-[#B87333] rounded-2xl overflow-hidden transition-all hover:scale-[1.02] shadow-xl">
      {/* Image */}
      <div className="relative h-56 overflow-hidden">
        <Link href={`/property/${property.slug}`}>
          <Image
            src={getCoverPhoto(property.property_photos || [])}
            alt={property.title}
            fill
            className="object-cover group-hover:scale-110 transition-transform duration-500"
            unoptimized
          />
        </Link>
        
        {property.featured && (
          <div className="absolute top-4 left-4 px-3 py-1 bg-[#FFD700] text-[#0a0a0a] font-bold rounded-full text-sm z-10">
            Ô¡É Featured
          </div>
        )}
        
        <div className="absolute top-4 right-4 px-3 py-1 bg-[#B87333] text-white font-semibold rounded-full text-sm z-10 capitalize">
          {property.transaction_type}
        </div>

        {/* Favorite Button */}
        {onFavorite && (
          <button
            onClick={(e) => {
              e.preventDefault();
              onFavorite();
            }}
            className="absolute bottom-4 right-4 p-3 bg-black/60 hover:bg-black/80 rounded-full transition z-10"
            aria-label="Add to favorites"
          >
            <Heart
              className={`w-5 h-5 ${isFavorited ? 'fill-red-500 text-red-500' : 'text-white'}`}
            />
          </button>
        )}
      </div>

      {/* Content */}
      <div className="p-5">
        {/* Type Badge */}
        <div className="flex items-center gap-2 mb-3">
          <IconComponent className="w-4 h-4 text-[#B87333]" />
          <span className="text-sm text-[#676767] capitalize">
            {getPropertyTypeLabel(property.property_type)}
          </span>
        </div>

        {/* Title */}
        <Link href={`/property/${property.slug}`}>
          <h3 className="text-xl font-bold text-[#e6c86b] mb-2 line-clamp-2 group-hover:text-[#FFD700] transition">
            {property.title}
          </h3>
        </Link>

        {/* Location */}
        <div className="flex items-center gap-2 text-sm text-[#676767] mb-4">
          <MapPin className="w-4 h-4" />
          <span>{property.city}, {property.state}</span>
        </div>

        {/* Features */}
        <div className="flex items-center gap-4 mb-4 text-sm text-[#d8c68e]">
          {property.bedrooms && property.bedrooms > 0 && (
            <div className="flex items-center gap-1">
              <BedDouble className="w-4 h-4" />
              <span>{property.bedrooms}</span>
            </div>
          )}
          {property.bathrooms && property.bathrooms > 0 && (
            <div className="flex items-center gap-1">
              <Bath className="w-4 h-4" />
              <span>{property.bathrooms}</span>
            </div>
          )}
          {property.parking_spaces && property.parking_spaces > 0 && (
            <div className="flex items-center gap-1">
              <Car className="w-4 h-4" />
              <span>{property.parking_spaces}</span>
            </div>
          )}
          {property.total_area && property.total_area > 0 && (
            <div className="flex items-center gap-1">
              <Ruler className="w-4 h-4" />
              <span>{property.total_area}m┬▓</span>
            </div>
          )}
        </div>

        {/* Price */}
        <div className="flex items-center justify-between">
          <div className="text-2xl font-bold text-[#B87333]">
            {formatPrice(property.price)}
          </div>

          {showFazerProposta && onFazerProposta && (
            <button
              onClick={onFazerProposta}
              className="px-4 py-2 bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold rounded-lg transition-all text-sm"
            >
              Fazer Proposta
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { createBrowserSupabaseClient } from "@/lib/supabaseBrowser";
import { Calendar, Clock, User, Phone, Mail, X, Check, AlertCircle } from "lucide-react";

interface ScheduleVisitModalProps {
  propertyId: string;
  propertyTitle: string;
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export default function ScheduleVisitModal({
  propertyId,
  propertyTitle,
  isOpen,
  onClose,
  onSuccess,
}: ScheduleVisitModalProps) {
  const supabase = createBrowserSupabaseClient();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  // Form fields
  const [selectedDate, setSelectedDate] = useState('');
  const [selectedTime, setSelectedTime] = useState('');
  const [visitorName, setVisitorName] = useState('');
  const [visitorPhone, setVisitorPhone] = useState('');
  const [visitorEmail, setVisitorEmail] = useState('');
  const [message, setMessage] = useState('');

  const timeSlots = [
    '09:00', '10:00', '11:00', '12:00',
    '14:00', '15:00', '16:00', '17:00', '18:00'
  ];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('You must be logged in to schedule a visit');
      }

      // Create visit request
      const { data, error: visitError } = await supabase
        .from('visits')
        .insert({
          user_id: user.id,
          property_id: propertyId,
          scheduled_date: selectedDate,
          scheduled_time: selectedTime,
          visitor_name: visitorName,
          visitor_phone: visitorPhone,
          visitor_email: visitorEmail,
          message: message,
          status: 'pending', // Will need confirmation
        })
        .select()
        .single();

      if (visitError) throw visitError;

      setSuccess(true);
      setTimeout(() => {
        onClose();
        if (onSuccess) onSuccess();
      }, 2000);

    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message || 'Failed to schedule visit');
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-[#0a0a0a] border-b border-[#2a2a1a] p-6 flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold text-[#B87333] mb-1">Schedule a Visit</h2>
            <p className="text-sm text-[#676767]">{propertyTitle}</p>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-[#2a2a1a] rounded-lg transition"
            aria-label="Close modal"
          >
            <X className="w-6 h-6 text-[#676767]" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6">
          {error && (
            <div className="mb-6 p-4 bg-red-500/10 border border-red-500 rounded-lg flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
              <p className="text-red-500">{error}</p>
            </div>
          )}

          {success && (
            <div className="mb-6 p-4 bg-green-500/10 border border-green-500 rounded-lg flex items-start gap-3">
              <Check className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-green-500 font-semibold mb-1">Visit Scheduled Successfully!</p>
                <p className="text-sm text-green-400">
                  You will receive a confirmation email shortly. The property owner will confirm your visit.
                </p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Date and Time */}
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2 flex items-center gap-2">
                  <Calendar className="w-4 h-4" />
                  Preferred Date *
                </label>
                <input
                  required
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  min={new Date().toISOString().split('T')[0]}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2 flex items-center gap-2">
                  <Clock className="w-4 h-4" />
                  Preferred Time *
                </label>
                <select
                  required
                  value={selectedTime}
                  onChange={(e) => setSelectedTime(e.target.value)}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                >
                  <option value="">Select time</option>
                  {timeSlots.map(time => (
                    <option key={time} value={time}>{time}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Visitor Information */}
            <div>
              <label className="block text-sm font-semibold text-[#d8c68e] mb-2 flex items-center gap-2">
                <User className="w-4 h-4" />
                Full Name *
              </label>
              <input
                required
                type="text"
                value={visitorName}
                onChange={(e) => setVisitorName(e.target.value)}
                placeholder="Your full name"
                className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
              />
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2 flex items-center gap-2">
                  <Phone className="w-4 h-4" />
                  Phone Number *
                </label>
                <input
                  required
                  type="tel"
                  value={visitorPhone}
                  onChange={(e) => setVisitorPhone(e.target.value)}
                  placeholder="+1 (555) 000-0000"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2 flex items-center gap-2">
                  <Mail className="w-4 h-4" />
                  Email Address *
                </label>
                <input
                  required
                  type="email"
                  value={visitorEmail}
                  onChange={(e) => setVisitorEmail(e.target.value)}
                  placeholder="your@email.com"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>
            </div>

            {/* Message */}
            <div>
              <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                Additional Message (Optional)
              </label>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                rows={4}
                placeholder="Any questions or special requests..."
                className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
              />
            </div>

            {/* Important Notice */}
            <div className="bg-[#B87333]/10 border border-[#B87333]/30 rounded-lg p-4">
              <p className="text-sm text-[#d8c68e]">
                <strong className="text-[#B87333]">Important:</strong> After the property owner confirms your visit 
                and you complete it, you will be able to submit a proposal for this property.
              </p>
            </div>

            {/* Submit Button */}
            <div className="flex gap-4">
              <button
                type="submit"
                disabled={loading || success}
                className="flex-1 bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold py-4 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                {loading ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Scheduling...
                  </>
                ) : success ? (
                  <>
                    <Check className="w-5 h-5" />
                    Scheduled!
                  </>
                ) : (
                  <>
                    <Calendar className="w-5 h-5" />
                    Schedule Visit
                  </>
                )}
              </button>
              <button
                type="button"
                onClick={onClose}
                className="px-8 py-4 border-2 border-[#2a2a1a] hover:border-[#B87333] text-[#d8c68e] font-semibold rounded-lg transition"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { createBrowserSupabaseClient } from "@/lib/supabaseBrowser";
import { useRouter } from "next/navigation";
import { Heart, Trash2, Search } from "lucide-react";
import { PropertyCard } from "@publimicro/ui";

export default function FavoritesPage() {
  const router = useRouter();
  const supabase = createBrowserSupabaseClient();

  type FavoriteShape = {
    id: string;
    property: {
      id: string;
      title?: string;
      description?: string;
      property_type?: string;
      transaction_type?: string;
      price?: number;
      bedrooms?: number;
      bathrooms?: number;
      parking_spaces?: number;
      total_area?: number;
      city?: string;
      state?: string;
      slug?: string;
      featured?: boolean;
      property_photos?: Array<{ url?: string; is_cover?: boolean }>;
    };
  };

  const [favorites, setFavorites] = useState<FavoriteShape[]>([]);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState<{ id: string; email?: string } | null>(null);

  useEffect(() => {
    checkUser();
  }, []);

  const checkUser = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      router.push('/entrar');
      return;
    }
    setUser(user);
    fetchFavorites(user.id);
  };

  const fetchFavorites = async (userId: string) => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('property_favorites')
        .select(`
          id,
          created_at,
          property:properties (
            id,
            title,
            description,
            property_type,
            transaction_type,
            price,
            bedrooms,
            bathrooms,
            parking_spaces,
            total_area,
            city,
            state,
            country,
            slug,
            featured,
            property_photos (url, is_cover)
          )
        `)
        .eq('user_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setFavorites(data || []);
    } catch (error) {
      console.error('Error fetching favorites:', error);
    } finally {
      setLoading(false);
    }
  };

  const removeFavorite = async (favoriteId: string) => {
    try {
      const { error } = await supabase
        .from('property_favorites')
        .delete()
        .eq('id', favoriteId);

      if (error) throw error;

      // Update local state
      setFavorites(prev => prev.filter(fav => fav.id !== favoriteId));
    } catch (error) {
      console.error('Error removing favorite:', error);
    }
  };

  const handleFazerProposta = (propertyId: string) => {
    // Check visit status and redirect accordingly
    router.push(`/property/${propertyId}#fazer-proposta`);
  };

  return (
    <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-[#B87333] via-[#DAA520] to-[#FFD700] bg-clip-text text-transparent mb-3 flex items-center gap-3">
            <Heart className="w-10 h-10 text-[#B87333] fill-[#B87333]" />
            My Favorites
          </h1>
          <p className="text-[#d8c68e] text-lg">
            Properties you've saved for later
          </p>
        </div>

        {loading ? (
          <div className="text-center py-20">
            <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-[#B87333] border-t-transparent"></div>
            <p className="mt-4 text-[#d8c68e]">Loading favorites...</p>
          </div>
        ) : favorites.length === 0 ? (
          <div className="text-center py-20">
            <Heart className="w-20 h-20 text-[#676767] mx-auto mb-6" />
            <h2 className="text-3xl font-bold text-[#d8c68e] mb-3">No favorites yet</h2>
            <p className="text-[#676767] mb-8 max-w-md mx-auto">
              Start exploring properties and add them to your favorites by clicking the heart icon
            </p>
            <button
              onClick={() => router.push('/search')}
              className="inline-flex items-center gap-2 px-8 py-4 bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold rounded-lg transition-all"
            >
              <Search className="w-5 h-5" />
              Browse Properties
            </button>
          </div>
        ) : (
          <>
            <div className="mb-6">
              <p className="text-[#d8c68e]">
                <span className="font-bold text-[#B87333]">{favorites.length}</span> 
                {favorites.length === 1 ? ' property' : ' properties'} saved
              </p>
            </div>

            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {favorites.map((favorite) => (
                <div key={favorite.id} className="relative">
                  <PropertyCard
                    id={favorite.property.id}
                    title={favorite.property.title}
                    description={favorite.property.description}
                    price={favorite.property.price}
                    featured={favorite.property.featured}
                    location={{
                      city: favorite.property.city,
                      state: favorite.property.state,
                      neighborhood: undefined
                    }}
                    area={{
                      total: favorite.property.total_area || 0
                    }}
                    features={{
                      bedrooms: favorite.property.bedrooms,
                      bathrooms: favorite.property.bathrooms,
                      parking: favorite.property.parking_spaces
                    }}
                    photos={favorite.property.property_photos?.map((p: { url?: string }) => p.url) || []}
                    link={`/property/${favorite.property.slug}`}
                    type="property"
                  />
                  
                  {/* Remove button overlay */}
                  <button
                    onClick={() => removeFavorite(favorite.id)}
                    className="absolute top-4 left-4 p-2 bg-red-500 hover:bg-red-600 text-white rounded-full transition z-20 shadow-lg"
                    aria-label="Remove from favorites"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </main>
  );
}

"use client";

import { useState } from "react";
import { createBrowserSupabaseClient } from "@/lib/supabaseBrowser";
import { useRouter } from "next/navigation";
import { 
  Building2, Home, Trees, Waves, Upload, X, Plus,
  MapPin, DollarSign, Ruler, BedDouble, Bath, Car,
  Zap, Wifi, Droplet, Check, AlertCircle
} from "lucide-react";

const PROPERTY_TYPES = [
  { value: '', label: 'Select Property Type', icon: Building2 },
  { value: 'apartment', label: 'Apartment', icon: Building2, needsRooms: true },
  { value: 'house', label: 'House', icon: Home, needsRooms: true, needsLand: true },
  { value: 'chacara', label: 'Ch├ícara (Small Rural <2ha)', icon: Trees, needsRural: true, isRural: true },
  { value: 'sitio', label: 'S├¡tio (2-50 hectares)', icon: Trees, needsRural: true, isRural: true },
  { value: 'fazenda', label: 'Fazenda (50+ hectares)', icon: Trees, needsRural: true, isRural: true },
  { value: 'rancho', label: 'Rancho (Near Water 2+ ha)', icon: Waves, needsRural: true, needsWater: true, isRural: true },
  { value: 'commercial', label: 'Commercial Property', icon: Building2 },
  { value: 'land', label: 'Land/Lot', icon: MapPin },
];

const AMENITIES = [
  'pool', 'gym', 'playground', 'sports_court', 'party_room', 'sauna',
  'garden', 'barbecue', 'gourmet_kitchen', 'home_office', 'balcony',
  'terrace', 'storage', 'laundry_room', 'service_area', 'maid_room',
  'solar_heating', 'air_conditioning', 'fireplace', 'wine_cellar',
  'home_theater', 'stable', 'barn', 'warehouse', 'chicken_coop',
  'orchard', 'crop_field', 'pasture_land', 'fencing', 'irrigation_system'
];

export default function PostPropertyPage() {
  const router = useRouter();
  const supabase = createBrowserSupabaseClient();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  // Basic Info
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [propertyType, setPropertyType] = useState('');
  const [transactionType, setTransactionType] = useState('sale');

  // Pricing
  const [price, setPrice] = useState('');
  const [condominiumFee, setCondominiumFee] = useState('');
  const [iptuAnnual, setIptuAnnual] = useState('');
  const [acceptsFinancing, setAcceptsFinancing] = useState(true);
  const [acceptsExchange, setAcceptsExchange] = useState(false);

  // Location
  const [country, setCountry] = useState('Brazil');
  const [state, setState] = useState('');
  const [city, setCity] = useState('');
  const [neighborhood, setNeighborhood] = useState('');
  const [address, setAddress] = useState('');
  const [zipCode, setZipCode] = useState('');

  // Areas
  const [totalArea, setTotalArea] = useState('');
  const [builtArea, setBuiltArea] = useState('');
  const [landArea, setLandArea] = useState('');

  // Rooms (Urban)
  const [bedrooms, setBedrooms] = useState('');
  const [bathrooms, setBathrooms] = useState('');
  const [suites, setSuites] = useState('');
  const [parkingSpaces, setParkingSpaces] = useState('');

  // Rural Features
  const [waterSource, setWaterSource] = useState('');
  const [hasElectricity, setHasElectricity] = useState(false);
  const [hasInternet, setHasInternet] = useState(false);
  const [soilQuality, setSoilQuality] = useState('');
  const [topography, setTopography] = useState('');
  const [vegetationType, setVegetationType] = useState('');
  const [nearWater, setNearWater] = useState(false);
  const [waterDistance, setWaterDistance] = useState('');

  // Building Features
  const [yearBuilt, setYearBuilt] = useState('');
  const [floors, setFloors] = useState('');
  const [furnished, setFurnished] = useState(false);

  // Documents
  const [hasDeed, setHasDeed] = useState(false);
  const [hasRegistration, setHasRegistration] = useState(false);

  // Amenities
  const [selectedAmenities, setSelectedAmenities] = useState<string[]>([]);

  // Photos
  const [photos, setPhotos] = useState<File[]>([]);

  const selectedTypeConfig = PROPERTY_TYPES.find(t => t.value === propertyType);

  const toggleAmenity = (amenity: string) => {
    setSelectedAmenities(prev =>
      prev.includes(amenity)
        ? prev.filter(a => a !== amenity)
        : [...prev, amenity]
    );
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setPhotos(prev => [...prev, ...Array.from(e.target.files!)]);
    }
  };

  const removePhoto = (index: number) => {
    setPhotos(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        throw new Error('You must be logged in to post a property');
      }

      // Create property
      const propertyData = {
        user_id: user.id,
        title,
        description,
        property_type: propertyType,
        transaction_type: transactionType,
        price: parseFloat(price),
        condominium_fee: condominiumFee ? parseFloat(condominiumFee) : null,
        iptu_annual: iptuAnnual ? parseFloat(iptuAnnual) : null,
        accepts_financing: acceptsFinancing,
        accepts_exchange: acceptsExchange,
        country,
        state,
        city,
        neighborhood,
        address,
        zip_code: zipCode,
        total_area: totalArea ? parseFloat(totalArea) : null,
        built_area: builtArea ? parseFloat(builtArea) : null,
        land_area: landArea ? parseFloat(landArea) : null,
        bedrooms: bedrooms ? parseInt(bedrooms) : 0,
        bathrooms: bathrooms ? parseInt(bathrooms) : 0,
        suites: suites ? parseInt(suites) : 0,
        parking_spaces: parkingSpaces ? parseInt(parkingSpaces) : 0,
        water_source: waterSource || null,
        has_electricity: hasElectricity,
        has_internet: hasInternet,
        soil_quality: soilQuality || null,
        topography: topography || null,
        vegetation_type: vegetationType || null,
        near_water: nearWater,
        water_distance_meters: waterDistance ? parseInt(waterDistance) : null,
        year_built: yearBuilt ? parseInt(yearBuilt) : null,
        floors: floors ? parseInt(floors) : 1,
        furnished,
        has_deed: hasDeed,
        has_registration: hasRegistration,
        status: 'pending', // Requires admin approval
      };

      const { data: property, error: propertyError } = await supabase
        .from('properties')
        .insert(propertyData)
        .select()
        .single();

      if (propertyError) throw propertyError;

      // Insert amenities
      if (selectedAmenities.length > 0) {
        const amenitiesData = selectedAmenities.map(amenity => ({
          property_id: property.id,
          amenity_type: amenity,
        }));

        const { error: amenitiesError } = await supabase
          .from('property_amenities')
          .insert(amenitiesData);

        if (amenitiesError) throw amenitiesError;
      }

      // Upload photos (simplified - in production use proper storage)
      // TODO: Implement photo upload to Supabase Storage

      setSuccess(true);
      setTimeout(() => {
        router.push('/proper');
      }, 2000);

    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message || 'Failed to create property listing');
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] py-12">
      <div className="max-w-4xl mx-auto px-4">
        <div className="mb-8">
          <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-[#B87333] via-[#DAA520] to-[#FFD700] bg-clip-text text-transparent mb-3">
            Post Your Property
          </h1>
          <p className="text-[#d8c68e]">Fill in the details to list your property</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500 rounded-lg flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
            <p className="text-red-500">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-500/10 border border-green-500 rounded-lg flex items-start gap-3">
            <Check className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
            <p className="text-green-500">Property submitted successfully! Redirecting...</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Basic Information */}
          <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <h2 className="text-2xl font-bold text-[#B87333] mb-6">Basic Information</h2>
            
            <div className="space-y-4">
              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Property Type *
                  </label>
                  <select
                    required
                    value={propertyType}
                    onChange={(e) => setPropertyType(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    {PROPERTY_TYPES.map(type => (
                      <option key={type.value} value={type.value}>
                        {type.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Transaction Type *
                  </label>
                  <select
                    required
                    value={transactionType}
                    onChange={(e) => setTransactionType(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    <option value="sale">For Sale</option>
                    <option value="rent">For Rent</option>
                    <option value="lease">For Lease</option>
                    <option value="auction">Auction</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Property Title *
                </label>
                <input
                  required
                  type="text"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="e.g., Beautiful 3-bedroom apartment in downtown"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Description *
                </label>
                <textarea
                  required
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  rows={6}
                  placeholder="Describe your property in detail..."
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>
            </div>
          </section>

          {/* Pricing */}
          <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <h2 className="text-2xl font-bold text-[#B87333] mb-6">Pricing</h2>
            
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Price (USD) *
                </label>
                <input
                  required
                  type="number"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  step="0.01"
                  min="0"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Condominium Fee (USD)
                </label>
                <input
                  type="number"
                  value={condominiumFee}
                  onChange={(e) => setCondominiumFee(e.target.value)}
                  placeholder="0.00"
                  step="0.01"
                  min="0"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Annual Property Tax (USD)
                </label>
                <input
                  type="number"
                  value={iptuAnnual}
                  onChange={(e) => setIptuAnnual(e.target.value)}
                  placeholder="0.00"
                  step="0.01"
                  min="0"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div className="flex flex-col gap-3">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={acceptsFinancing}
                    onChange={(e) => setAcceptsFinancing(e.target.checked)}
                    className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                  />
                  <span className="text-[#d8c68e]">Accepts Financing</span>
                </label>

                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={acceptsExchange}
                    onChange={(e) => setAcceptsExchange(e.target.checked)}
                    className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                  />
                  <span className="text-[#d8c68e]">Accepts Exchange</span>
                </label>
              </div>
            </div>
          </section>

          {/* Location */}
          <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <h2 className="text-2xl font-bold text-[#B87333] mb-6 flex items-center gap-2">
              <MapPin className="w-6 h-6" />
              Location
            </h2>
            
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Country *
                </label>
                <input
                  required
                  type="text"
                  value={country}
                  onChange={(e) => setCountry(e.target.value)}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  State/Region *
                </label>
                <input
                  required
                  type="text"
                  value={state}
                  onChange={(e) => setState(e.target.value)}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  City *
                </label>
                <input
                  required
                  type="text"
                  value={city}
                  onChange={(e) => setCity(e.target.value)}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Neighborhood
                </label>
                <input
                  type="text"
                  value={neighborhood}
                  onChange={(e) => setNeighborhood(e.target.value)}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Address
                </label>
                <input
                  type="text"
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  placeholder="Street address (optional for privacy)"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  ZIP/Postal Code
                </label>
                <input
                  type="text"
                  value={zipCode}
                  onChange={(e) => setZipCode(e.target.value)}
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>
            </div>
          </section>

          {/* Dimensions */}
          <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <h2 className="text-2xl font-bold text-[#B87333] mb-6 flex items-center gap-2">
              <Ruler className="w-6 h-6" />
              Dimensions
            </h2>
            
            <div className="grid md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                  Total Area {selectedTypeConfig?.isRural ? '(hectares)' : '(m┬▓)'} *
                </label>
                <input
                  required
                  type="number"
                  value={totalArea}
                  onChange={(e) => setTotalArea(e.target.value)}
                  step="0.01"
                  min="0"
                  className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                />
              </div>

              {selectedTypeConfig?.needsRooms && (
                <>
                  <div>
                    <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                      Built Area (m┬▓)
                    </label>
                    <input
                      type="number"
                      value={builtArea}
                      onChange={(e) => setBuiltArea(e.target.value)}
                      step="0.01"
                      min="0"
                      className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                    />
                  </div>

                  {selectedTypeConfig?.needsLand && (
                    <div>
                      <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                        Land Area (m┬▓)
                      </label>
                      <input
                        type="number"
                        value={landArea}
                        onChange={(e) => setLandArea(e.target.value)}
                        step="0.01"
                        min="0"
                        className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                      />
                    </div>
                  )}
                </>
              )}
            </div>
          </section>

          {/* Rooms & Features (Urban Properties) */}
          {selectedTypeConfig?.needsRooms && (
            <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
              <h2 className="text-2xl font-bold text-[#B87333] mb-6">Rooms & Features</h2>
              
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    <BedDouble className="w-4 h-4 inline mr-1" />
                    Bedrooms
                  </label>
                  <input
                    type="number"
                    value={bedrooms}
                    onChange={(e) => setBedrooms(e.target.value)}
                    min="0"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    <Bath className="w-4 h-4 inline mr-1" />
                    Bathrooms
                  </label>
                  <input
                    type="number"
                    value={bathrooms}
                    onChange={(e) => setBathrooms(e.target.value)}
                    min="0"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Suites
                  </label>
                  <input
                    type="number"
                    value={suites}
                    onChange={(e) => setSuites(e.target.value)}
                    min="0"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    <Car className="w-4 h-4 inline mr-1" />
                    Parking
                  </label>
                  <input
                    type="number"
                    value={parkingSpaces}
                    onChange={(e) => setParkingSpaces(e.target.value)}
                    min="0"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  />
                </div>
              </div>

              <div className="mt-4 grid md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Year Built
                  </label>
                  <input
                    type="number"
                    value={yearBuilt}
                    onChange={(e) => setYearBuilt(e.target.value)}
                    min="1800"
                    max={new Date().getFullYear()}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="flex items-center gap-2 cursor-pointer pt-8">
                    <input
                      type="checkbox"
                      checked={furnished}
                      onChange={(e) => setFurnished(e.target.checked)}
                      className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                    />
                    <span className="text-[#d8c68e]">Furnished</span>
                  </label>
                </div>
              </div>
            </section>
          )}

          {/* Rural Features */}
          {selectedTypeConfig?.needsRural && (
            <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
              <h2 className="text-2xl font-bold text-[#B87333] mb-6 flex items-center gap-2">
                <Trees className="w-6 h-6" />
                Rural Features
              </h2>
              
              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    <Droplet className="w-4 h-4 inline mr-1" />
                    Water Source
                  </label>
                  <select
                    value={waterSource}
                    onChange={(e) => setWaterSource(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    <option value="">Select</option>
                    <option value="river">River</option>
                    <option value="well">Well</option>
                    <option value="lake">Lake</option>
                    <option value="reservoir">Reservoir</option>
                    <option value="public">Public Water</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Soil Quality
                  </label>
                  <select
                    value={soilQuality}
                    onChange={(e) => setSoilQuality(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    <option value="">Select</option>
                    <option value="excellent">Excellent</option>
                    <option value="good">Good</option>
                    <option value="average">Average</option>
                    <option value="poor">Poor</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Topography
                  </label>
                  <select
                    value={topography}
                    onChange={(e) => setTopography(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    <option value="">Select</option>
                    <option value="flat">Flat</option>
                    <option value="hilly">Hilly</option>
                    <option value="mountainous">Mountainous</option>
                    <option value="mixed">Mixed</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Vegetation Type
                  </label>
                  <input
                    type="text"
                    value={vegetationType}
                    onChange={(e) => setVegetationType(e.target.value)}
                    placeholder="e.g., Forest, Pasture, Crops"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                <div className="flex flex-col gap-3">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={hasElectricity}
                      onChange={(e) => setHasElectricity(e.target.checked)}
                      className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                    />
                    <span className="text-[#d8c68e] flex items-center gap-1">
                      <Zap className="w-4 h-4" />
                      Has Electricity
                    </span>
                  </label>

                  <label className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={hasInternet}
                      onChange={(e) => setHasInternet(e.target.checked)}
                      className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                    />
                    <span className="text-[#d8c68e] flex items-center gap-1">
                      <Wifi className="w-4 h-4" />
                      Has Internet
                    </span>
                  </label>
                </div>

                {selectedTypeConfig?.needsWater && (
                  <>
                    <div>
                      <label className="flex items-center gap-2 cursor-pointer pt-3">
                        <input
                          type="checkbox"
                          checked={nearWater}
                          onChange={(e) => setNearWater(e.target.checked)}
                          className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                        />
                        <span className="text-[#d8c68e] flex items-center gap-1">
                          <Waves className="w-4 h-4" />
                          Near Water (River/Sea)
                        </span>
                      </label>
                      {nearWater && (
                        <input
                          type="number"
                          value={waterDistance}
                          onChange={(e) => setWaterDistance(e.target.value)}
                          placeholder="Distance in meters"
                          className="mt-2 w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                        />
                      )}
                    </div>
                  </>
                )}
              </div>
            </section>
          )}

          {/* Documents */}
          <section className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <h2 className="text-2xl font-bold text-[#B87333] mb-6">Legal Documents</h2>
            
            <div className="flex flex-col gap-3">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={hasDeed}
                  onChange={(e) => setHasDeed(e.target.checked)}
                  className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                />
                <span className="text-[#d8c68e]">Has Deed (Escritura)</span>
              </label>

              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={hasRegistration}
                  onChange={(e) => setHasRegistration(e.target.checked)}
                  className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                />
                <span className="text-[#d8c68e]">Has Registration (Matr├¡cula)</span>
              </label>
            </div>
          </section>

          {/* Submit Button */}
          <div className="flex gap-4">
            <button
              type="submit"
              disabled={loading}
              className="flex-1 bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold py-4 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? 'Submitting...' : 'Submit Property'}
            </button>
            <button
              type="button"
              onClick={() => router.back()}
              className="px-8 py-4 border-2 border-[#2a2a1a] hover:border-[#B87333] text-[#d8c68e] font-semibold rounded-lg transition"
            >
              Cancel
            </button>
          </div>

          <p className="text-sm text-[#676767] text-center">
            Your property will be reviewed by our team before being published. This usually takes 24-48 hours.
          </p>
        </form>
      </div>
    </main>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { createBrowserSupabaseClient } from "@/lib/supabaseBrowser";
import Image from "next/image";
import Link from "next/link";
import {
  MapPin, Ruler, BedDouble, Bath, Car, DollarSign, Heart,
  Phone, Mail, Calendar, Check, X, Home, Trees, Droplet,
  Zap, Wifi, ChevronLeft, ChevronRight, Share2, AlertCircle,
  Building2, Waves, Gavel
} from "lucide-react";
import { WhatsAppLink } from "@publimicro/ui";

interface Property {
  id: string;
  title: string;
  description: string;
  property_type: string;
  transaction_type: string;
  price: number;
  condominium_fee: number | null;
  iptu_annual: number | null;
  accepts_financing: boolean;
  accepts_exchange: boolean;
  country: string;
  state: string;
  city: string;
  neighborhood: string;
  address: string | null;
  total_area: number;
  built_area: number | null;
  land_area: number | null;
  bedrooms: number;
  bathrooms: number;
  suites: number;
  parking_spaces: number;
  water_source: string | null;
  has_electricity: boolean;
  has_internet: boolean;
  soil_quality: string | null;
  topography: string | null;
  vegetation_type: string | null;
  near_water: boolean;
  water_distance_meters: number | null;
  year_built: number | null;
  floors: number;
  furnished: boolean;
  has_deed: boolean;
  has_registration: boolean;
  featured: boolean;
  video_url: string | null;
  virtual_tour_url: string | null;
  views_count: number;
  favorites_count: number;
  user_id: string;
  created_at: string;
  property_photos: { url: string; caption: string; is_cover: boolean; display_order: number }[];
  property_amenities: { amenity_type: string }[];
}

const PROPERTY_TYPE_LABELS: Record<string, string> = {
  apartment: "Apartment",
  house: "House",
  chacara: "Ch├ícara",
  sitio: "S├¡tio",
  fazenda: "Fazenda",
  rancho: "Rancho",
  commercial: "Commercial",
  land: "Land",
};

export default function PropertyDetailPage() {
  const params = useParams();
  const router = useRouter();
  const supabase = createBrowserSupabaseClient();
  
  const [property, setProperty] = useState<Property | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);
  const [isFavorite, setIsFavorite] = useState(false);
  const [isCheckingVisit, setIsCheckingVisit] = useState(false);
  
  const slug = params.slug as string;

  useEffect(() => {
    fetchProperty();
    trackView();
  }, [slug]);

  const fetchProperty = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('properties')
        .select(`
          *,
          property_photos(url, caption, is_cover, display_order),
          property_amenities(amenity_type)
        `)
        .eq('slug', slug)
        .eq('status', 'active')
        .single();

      if (error) throw error;
      
      if (data) {
        // Sort photos by display_order
        data.property_photos.sort((a: { display_order?: number }, b: { display_order?: number }) => ((a.display_order ?? 0) - (b.display_order ?? 0)));
        setProperty(data);
        
        // Check if favorited
        const { data: { user } } = await supabase.auth.getUser();
        if (user) {
          const { data: fav } = await supabase
            .from('property_favorites')
            .select('id')
            .eq('property_id', data.id)
            .eq('user_id', user.id)
            .single();
          
          setIsFavorite(!!fav);
        }
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message || 'Property not found');
    } finally {
      setLoading(false);
    }
  };

  const trackView = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      
      await supabase.from('property_views').insert({
        property_id: property?.id,
        user_id: user?.id || null,
      });
    } catch (err) {
      // Silent fail for analytics
      console.error('View tracking error:', err);
    }
  };

  const handleFazerProposta = async () => {
    setIsCheckingVisit(true);
    
    try {
      // Step 1: Check if user is logged in
      const { data: { user } } = await supabase.auth.getUser();
      
      if (!user) {
        // Not logged in - redirect to sign in
        router.push(`/entrar?redirect=/property/${slug}`);
        return;
      }

      // Step 2: Check if user has completed a visit for this property
      const { data: visits, error: visitError } = await supabase
        .from('visits')
        .select('id, status')
        .eq('user_id', user.id)
        .eq('property_id', property?.id)
        .in('status', ['confirmed', 'completed']);

      if (visitError) throw visitError;

      if (!visits || visits.length === 0) {
        // No visit scheduled/completed - redirect to visit form
        router.push(`/schedule-visit?propertyId=${property?.id}`);
        return;
      }

      // Step 3: User is authorized - play auction sound and redirect to proposal
      playAuctionSound();
      
      setTimeout(() => {
        router.push(`/proposta?propId=${property?.id}`);
      }, 500);

    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      alert('Error checking authorization: ' + (message || 'Unknown error'));
    } finally {
      setIsCheckingVisit(false);
    }
  };

  const playAuctionSound = () => {
    const AudioContextClass = (window as unknown as { AudioContext?: new () => AudioContext; webkitAudioContext?: new () => AudioContext }).AudioContext || (window as unknown as { webkitAudioContext?: new () => AudioContext }).webkitAudioContext;
    const audioContext = new (AudioContextClass as new () => AudioContext)();
    const oscillator = audioContext.createOscillator();
    const gainNode = audioContext.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);

    oscillator.frequency.value = 800;
    oscillator.type = 'sine';

    gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);

    oscillator.start(audioContext.currentTime);
    oscillator.stop(audioContext.currentTime + 0.5);
  }; 

  const toggleFavorite = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.push('/entrar');
        return;
      }

      if (isFavorite) {
        await supabase
          .from('property_favorites')
          .delete()
          .eq('property_id', property?.id)
          .eq('user_id', user.id);
        setIsFavorite(false);
      } else {
        await supabase
          .from('property_favorites')
          .insert({
            property_id: property?.id,
            user_id: user.id,
          });
        setIsFavorite(true);
      }
    } catch (err) {
      console.error('Favorite error:', err);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
    }).format(price);
  };

  const nextPhoto = () => {
    if (property && property.property_photos.length > 0) {
      setCurrentPhotoIndex((prev) => 
        prev === property.property_photos.length - 1 ? 0 : prev + 1
      );
    }
  };

  const prevPhoto = () => {
    if (property && property.property_photos.length > 0) {
      setCurrentPhotoIndex((prev) => 
        prev === 0 ? property.property_photos.length - 1 : prev - 1
      );
    }
  };

  if (loading) {
    return (
      <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-[#B87333] border-t-transparent mb-4"></div>
          <p className="text-[#d8c68e]">Loading property...</p>
        </div>
      </main>
    );
  }

  if (error || !property) {
    return (
      <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] flex items-center justify-center">
        <div className="text-center max-w-md mx-auto px-4">
          <AlertCircle className="w-16 h-16 text-[#B87333] mx-auto mb-4" />
          <h1 className="text-2xl font-bold text-[#d8c68e] mb-2">Property Not Found</h1>
          <p className="text-[#676767] mb-6">{error || 'This property may have been removed or is no longer available.'}</p>
          <Link
            href="/proper/search"
            className="inline-block px-6 py-3 bg-gradient-to-r from-[#B87333] to-[#DAA520] text-white font-semibold rounded-lg hover:from-[#DAA520] hover:to-[#FFD700] transition"
          >
            Browse Properties
          </Link>
        </div>
      </main>
    );
  }

  const photos = property.property_photos.length > 0 
    ? property.property_photos 
    : [{ url: '/images/placeholder-property.jpg', caption: '', is_cover: true, display_order: 0 }];

  const isRural = ['chacara', 'sitio', 'fazenda', 'rancho'].includes(property.property_type);

  return (
    <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a]">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-8">
        {/* Back Button */}
        <Link
          href="/proper/search"
          className="inline-flex items-center gap-2 text-[#676767] hover:text-[#B87333] transition mb-6"
        >
          <ChevronLeft className="w-5 h-5" />
          Back to Search
        </Link>

        {/* Photo Gallery */}
        <div className="relative h-[500px] rounded-2xl overflow-hidden mb-8 group">
          <Image
            src={photos[currentPhotoIndex].url}
            alt={photos[currentPhotoIndex].caption || property.title}
            fill
            className="object-cover"
            unoptimized
          />
          
          {/* Photo Navigation */}
          {photos.length > 1 && (
            <>
              <button
                onClick={prevPhoto}
                className="absolute left-4 top-1/2 -translate-y-1/2 bg-black/50 hover:bg-black/70 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition"
              >
                <ChevronLeft className="w-6 h-6" />
              </button>
              <button
                onClick={nextPhoto}
                className="absolute right-4 top-1/2 -translate-y-1/2 bg-black/50 hover:bg-black/70 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition"
              >
                <ChevronRight className="w-6 h-6" />
              </button>
              
              {/* Photo Counter */}
              <div className="absolute bottom-4 right-4 bg-black/70 text-white px-3 py-1 rounded-full text-sm">
                {currentPhotoIndex + 1} / {photos.length}
              </div>
            </>
          )}

          {/* Featured Badge */}
          {property.featured && (
            <div className="absolute top-4 left-4 px-4 py-2 bg-[#FFD700] text-[#0a0a0a] font-bold rounded-full">
              Ô¡É Featured
            </div>
          )}

          {/* Transaction Type Badge */}
          <div className="absolute top-4 right-4 px-4 py-2 bg-[#B87333] text-white font-semibold rounded-full capitalize">
            {property.transaction_type}
          </div>
        </div>

        <div className="grid lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-8">
            {/* Title & Price */}
            <div>
              <div className="flex items-center gap-3 mb-3">
                <span className="px-3 py-1 bg-[#B87333]/20 border border-[#B87333] rounded-full text-[#B87333] text-sm font-semibold capitalize">
                  {PROPERTY_TYPE_LABELS[property.property_type] || property.property_type}
                </span>
                {isRural && (
                  <span className="px-3 py-1 bg-[#6B8E23]/20 border border-[#6B8E23] rounded-full text-[#6B8E23] text-sm font-semibold">
                    Rural Property
                  </span>
                )}
              </div>

              <h1 className="text-4xl md:text-5xl font-bold text-[#e6c86b] mb-4">
                {property.title}
              </h1>

              <div className="flex items-center gap-2 text-[#676767] mb-6">
                <MapPin className="w-5 h-5" />
                <span className="text-lg">
                  {property.neighborhood && `${property.neighborhood}, `}
                  {property.city}, {property.state}, {property.country}
                </span>
              </div>

              <div className="text-5xl font-bold text-[#B87333]">
                {formatPrice(property.price)}
              </div>

              {property.condominium_fee && (
                <p className="text-[#676767] mt-2">
                  + {formatPrice(property.condominium_fee)}/month condominium fee
                </p>
              )}
            </div>

            {/* Key Features */}
            <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
              <h2 className="text-2xl font-bold text-[#B87333] mb-4">Key Features</h2>
              
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {property.bedrooms > 0 && (
                  <div className="text-center p-4 bg-[#0a0a0a] rounded-lg">
                    <BedDouble className="w-8 h-8 text-[#B87333] mx-auto mb-2" />
                    <div className="text-2xl font-bold text-[#e6c86b]">{property.bedrooms}</div>
                    <div className="text-sm text-[#676767]">Bedrooms</div>
                  </div>
                )}
                
                {property.bathrooms > 0 && (
                  <div className="text-center p-4 bg-[#0a0a0a] rounded-lg">
                    <Bath className="w-8 h-8 text-[#B87333] mx-auto mb-2" />
                    <div className="text-2xl font-bold text-[#e6c86b]">{property.bathrooms}</div>
                    <div className="text-sm text-[#676767]">Bathrooms</div>
                  </div>
                )}
                
                {property.parking_spaces > 0 && (
                  <div className="text-center p-4 bg-[#0a0a0a] rounded-lg">
                    <Car className="w-8 h-8 text-[#B87333] mx-auto mb-2" />
                    <div className="text-2xl font-bold text-[#e6c86b]">{property.parking_spaces}</div>
                    <div className="text-sm text-[#676767]">Parking</div>
                  </div>
                )}
                
                {property.total_area > 0 && (
                  <div className="text-center p-4 bg-[#0a0a0a] rounded-lg">
                    <Ruler className="w-8 h-8 text-[#B87333] mx-auto mb-2" />
                    <div className="text-2xl font-bold text-[#e6c86b]">{property.total_area}</div>
                    <div className="text-sm text-[#676767]">{isRural ? 'Hectares' : 'm┬▓'}</div>
                  </div>
                )}
              </div>

              {/* Additional Urban Features */}
              {!isRural && (
                <div className="mt-6 flex flex-wrap gap-3">
                  {property.built_area && (
                    <div className="px-4 py-2 bg-[#0a0a0a] rounded-lg text-sm">
                      <span className="text-[#676767]">Built:</span>{' '}
                      <span className="text-[#d8c68e] font-semibold">{property.built_area}m┬▓</span>
                    </div>
                  )}
                  {property.year_built && (
                    <div className="px-4 py-2 bg-[#0a0a0a] rounded-lg text-sm">
                      <span className="text-[#676767]">Year:</span>{' '}
                      <span className="text-[#d8c68e] font-semibold">{property.year_built}</span>
                    </div>
                  )}
                  {property.furnished && (
                    <div className="px-4 py-2 bg-[#0a0a0a] rounded-lg text-sm text-[#6B8E23] font-semibold">
                      Ô£ô Furnished
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Rural Features */}
            {isRural && (
              <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
                <h2 className="text-2xl font-bold text-[#B87333] mb-4 flex items-center gap-2">
                  <Trees className="w-6 h-6" />
                  Rural Features
                </h2>
                
                <div className="grid md:grid-cols-2 gap-4">
                  {property.water_source && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <Droplet className="w-5 h-5 text-[#4A90E2]" />
                      <div>
                        <div className="text-sm text-[#676767]">Water Source</div>
                        <div className="text-[#d8c68e] font-semibold capitalize">{property.water_source}</div>
                      </div>
                    </div>
                  )}

                  {property.has_electricity && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <Zap className="w-5 h-5 text-[#FFD700]" />
                      <div className="text-[#d8c68e] font-semibold">Electricity Available</div>
                    </div>
                  )}

                  {property.has_internet && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <Wifi className="w-5 h-5 text-[#4A90E2]" />
                      <div className="text-[#d8c68e] font-semibold">Internet Available</div>
                    </div>
                  )}

                  {property.soil_quality && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <div>
                        <div className="text-sm text-[#676767]">Soil Quality</div>
                        <div className="text-[#d8c68e] font-semibold capitalize">{property.soil_quality}</div>
                      </div>
                    </div>
                  )}

                  {property.topography && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <div>
                        <div className="text-sm text-[#676767]">Topography</div>
                        <div className="text-[#d8c68e] font-semibold capitalize">{property.topography}</div>
                      </div>
                    </div>
                  )}

                  {property.vegetation_type && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <div>
                        <div className="text-sm text-[#676767]">Vegetation</div>
                        <div className="text-[#d8c68e] font-semibold">{property.vegetation_type}</div>
                      </div>
                    </div>
                  )}

                  {property.near_water && (
                    <div className="flex items-center gap-3 p-3 bg-[#0a0a0a] rounded-lg">
                      <Waves className="w-5 h-5 text-[#4A90E2]" />
                      <div>
                        <div className="text-[#d8c68e] font-semibold">Near Water</div>
                        {property.water_distance_meters && (
                          <div className="text-sm text-[#676767]">{property.water_distance_meters}m away</div>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Description */}
            <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
              <h2 className="text-2xl font-bold text-[#B87333] mb-4">Description</h2>
              <p className="text-[#d8c68e] whitespace-pre-line leading-relaxed">
                {property.description}
              </p>
            </div>

            {/* Amenities */}
            {property.property_amenities.length > 0 && (
              <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
                <h2 className="text-2xl font-bold text-[#B87333] mb-4">Amenities</h2>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {property.property_amenities.map((amenity, index) => (
                    <div key={index} className="flex items-center gap-2 text-[#d8c68e]">
                      <Check className="w-4 h-4 text-[#6B8E23]" />
                      <span className="capitalize">{amenity.amenity_type.replace('_', ' ')}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Legal Documents */}
            <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
              <h2 className="text-2xl font-bold text-[#B87333] mb-4">Legal Documents</h2>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  {property.has_deed ? (
                    <Check className="w-5 h-5 text-[#6B8E23]" />
                  ) : (
                    <X className="w-5 h-5 text-[#676767]" />
                  )}
                  <span className={property.has_deed ? 'text-[#d8c68e]' : 'text-[#676767]'}>
                    Property Deed (Escritura)
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  {property.has_registration ? (
                    <Check className="w-5 h-5 text-[#6B8E23]" />
                  ) : (
                    <X className="w-5 h-5 text-[#676767]" />
                  )}
                  <span className={property.has_registration ? 'text-[#d8c68e]' : 'text-[#676767]'}>
                    Property Registration (Matr├¡cula)
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Sidebar - Contact & Actions */}
          <div className="lg:col-span-1">
            <div className="sticky top-24 space-y-4">
              {/* Fazer Proposta Button */}
              <button
                onClick={handleFazerProposta}
                disabled={isCheckingVisit}
                className="w-full bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold py-4 rounded-lg transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-xl"
              >
                <Gavel className="w-5 h-5" />
                {isCheckingVisit ? 'Checking...' : 'Fazer Proposta'}
              </button>

              {/* Schedule Visit */}
              <Link
                href={`/schedule-visit?propertyId=${property.id}`}
                className="w-full bg-[#1a1a1a] hover:bg-[#2a2a1a] border-2 border-[#B87333] text-[#B87333] font-semibold py-4 rounded-lg transition-all flex items-center justify-center gap-2"
              >
                <Calendar className="w-5 h-5" />
                Schedule Visit
              </Link>

              {/* Favorite */}
              <button
                onClick={toggleFavorite}
                className={`w-full ${
                  isFavorite
                    ? 'bg-[#B87333] text-white'
                    : 'bg-[#1a1a1a] border-2 border-[#2a2a1a] text-[#d8c68e]'
                } hover:bg-[#B87333] hover:text-white font-semibold py-4 rounded-lg transition-all flex items-center justify-center gap-2`}
              >
                <Heart className={`w-5 h-5 ${isFavorite ? 'fill-current' : ''}`} />
                {isFavorite ? 'Saved' : 'Save Property'}
              </button>

              {/* Share */}
              <button
                onClick={() => {
                  if (navigator.share) {
                    navigator.share({
                      title: property.title,
                      text: property.description,
                      url: window.location.href,
                    });
                  } else {
                    navigator.clipboard.writeText(window.location.href);
                    alert('Link copied to clipboard!');
                  }
                }}
                className="w-full bg-[#1a1a1a] hover:bg-[#2a2a1a] border-2 border-[#2a2a1a] text-[#d8c68e] font-semibold py-4 rounded-lg transition-all flex items-center justify-center gap-2"
              >
                <Share2 className="w-5 h-5" />
                Share
              </button>

              {/* Contact Info */}
              <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
                <h3 className="text-xl font-bold text-[#B87333] mb-4">Contact Seller</h3>
                
                <div className="space-y-3">
                  <WhatsAppLink
                    number="5534992610004"
                    message={`Hi, I'm interested in ${property.title}`}
                    className="flex items-center gap-3 p-3 bg-[#25D366] hover:bg-[#20BA5A] text-white rounded-lg transition"
                  >
                    <Phone className="w-5 h-5" />
                    <span className="font-semibold">WhatsApp</span>
                  </WhatsAppLink>

                  <a
                    href={`mailto:contact@acheme.com?subject=Property Inquiry: ${property.title}`}
                    className="flex items-center gap-3 p-3 bg-[#0a0a0a] hover:bg-[#1a1a1a] border border-[#2a2a1a] text-[#d8c68e] rounded-lg transition"
                  >
                    <Mail className="w-5 h-5" />
                    <span className="font-semibold">Email</span>
                  </a>
                </div>
              </div>

              {/* Property Stats */}
              <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
                <div className="space-y-3 text-sm">
                  <div className="flex justify-between">
                    <span className="text-[#676767]">Views</span>
                    <span className="text-[#d8c68e] font-semibold">{property.views_count}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-[#676767]">Favorites</span>
                    <span className="text-[#d8c68e] font-semibold">{property.favorites_count}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-[#676767]">Listed</span>
                    <span className="text-[#d8c68e] font-semibold">
                      {new Date(property.created_at).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              </div>

              {/* Financing & Exchange */}
              {(property.accepts_financing || property.accepts_exchange) && (
                <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
                  <h3 className="text-lg font-bold text-[#B87333] mb-3">Payment Options</h3>
                  <div className="space-y-2">
                    {property.accepts_financing && (
                      <div className="flex items-center gap-2 text-[#d8c68e]">
                        <Check className="w-4 h-4 text-[#6B8E23]" />
                        <span>Accepts Financing</span>
                      </div>
                    )}
                    {property.accepts_exchange && (
                      <div className="flex items-center gap-2 text-[#d8c68e]">
                        <Check className="w-4 h-4 text-[#6B8E23]" />
                        <span>Accepts Exchange</span>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}

"use client";

import { useState, useEffect, Suspense } from "react";
import { createBrowserSupabaseClient } from "@/lib/supabaseBrowser";
import { useRouter, useSearchParams } from "next/navigation";
import { 
  DollarSign, FileText, Check, AlertCircle, TrendingUp,
  Home, Calendar, User
} from "lucide-react";

function ProposalContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const supabase = createBrowserSupabaseClient();
  
  const propertyId = searchParams.get('propertyId');
  
  const [loading, setLoading] = useState(false);
  const [checking, setChecking] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  interface ProposalProperty {
    id: string;
    title?: string;
    price?: number;
    city?: string;
    state?: string;
    slug?: string;
    property_type?: string;
    transaction_type?: string;
  }

  const [property, setProperty] = useState<ProposalProperty | null>(null);
  const [user, setUser] = useState<{ id: string; email?: string } | null>(null);
  const [visitCompleted, setVisitCompleted] = useState(false);

  // Form fields
  const [bidAmount, setBidAmount] = useState('');
  const [useFinancing, setUseFinancing] = useState(false);
  const [downPayment, setDownPayment] = useState('');
  const [message, setMessage] = useState('');
  const [acceptTerms, setAcceptTerms] = useState(false);

  useEffect(() => {
    if (propertyId) {
      checkAuthorization();
    } else {
      setError('Property ID is required');
      setChecking(false);
    }
  }, [propertyId]);

  const checkAuthorization = async () => {
    setChecking(true);
    try {
      // Check if user is logged in
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.push(`/entrar?redirect=/proposta?propertyId=${propertyId}`);
        return;
      }
      setUser(user);

      // Fetch property details
      const { data: propertyData, error: propError } = await supabase
        .from('properties')
        .select('*')
        .eq('id', propertyId)
        .single();

      if (propError) throw propError;
      setProperty(propertyData);

      // Check if user has completed a visit
      const { data: visitData, error: visitError } = await supabase
        .from('visits')
        .select('*')
        .eq('property_id', propertyId)
        .eq('user_id', user.id)
        .in('status', ['confirmed', 'completed'])
        .order('created_at', { ascending: false })
        .limit(1);

      if (visitError) throw visitError;

      if (!visitData || visitData.length === 0) {
        // No visit found - redirect to schedule visit
        router.push(`/property/${propertyData.slug}#schedule-visit`);
        return;
      }

      setVisitCompleted(true);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message || 'Failed to verify authorization');
    } finally {
      setChecking(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!acceptTerms) {
      setError('You must accept the terms and conditions');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Create bid/proposal
      const { data, error: bidError } = await supabase
        .from('bids')
        .insert({
          property_id: propertyId,
          user_id: user.id,
          amount: parseFloat(bidAmount),
          use_financing: useFinancing,
          down_payment: downPayment ? parseFloat(downPayment) : null,
          message: message,
          status: 'pending',
        })
        .select()
        .single();

      if (bidError) throw bidError;

      // Play auction sound (cross-browser AudioContext handling)
      const AudioContextClass = (window as unknown as { AudioContext?: new () => AudioContext; webkitAudioContext?: new () => AudioContext }).AudioContext || (window as unknown as { webkitAudioContext?: new () => AudioContext }).webkitAudioContext;
      const audioContext = new (AudioContextClass as new () => AudioContext)();
      const oscillator = audioContext.createOscillator();
      const gainNode = audioContext.createGain();
      
      oscillator.connect(gainNode);
      gainNode.connect(audioContext.destination);
      
      oscillator.frequency.value = 800;
      oscillator.type = 'sine';
      
      gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);
      
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.5);

      setSuccess(true);
      setTimeout(() => {
        router.push(`/lances`); // Redirect to user's bids page
      }, 3000);

    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message || 'Failed to submit proposal');
    } finally {
      setLoading(false);
    }
  };

  if (checking) {
    return (
      <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-[#B87333] border-t-transparent mb-4"></div>
          <p className="text-[#d8c68e]">Verifying authorization...</p>
        </div>
      </main>
    );
  }

  if (error && !property) {
    return (
      <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-red-500/30 rounded-2xl p-8 text-center">
          <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-red-500 mb-2">Error</h2>
          <p className="text-[#d8c68e] mb-6">{error}</p>
          <button
            onClick={() => router.back()}
            className="px-6 py-3 bg-[#2a2a1a] hover:bg-[#3a3a2a] text-[#d8c68e] rounded-lg transition"
          >
            Go Back
          </button>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a] py-12">
      <div className="max-w-3xl mx-auto px-4">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-[#B87333] via-[#DAA520] to-[#FFD700] bg-clip-text text-transparent mb-3">
            Fazer Proposta
          </h1>
          {property && (
            <div className="flex items-center gap-3 text-[#d8c68e]">
              <Home className="w-5 h-5" />
              <span className="text-lg">{property.title}</span>
            </div>
          )}
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500 rounded-lg flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
            <p className="text-red-500">{error}</p>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-green-500/10 border border-green-500 rounded-lg flex items-start gap-3">
            <Check className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-green-500 font-semibold mb-1">Proposal Submitted Successfully! ­ƒÄë</p>
              <p className="text-sm text-green-400">
                The property owner will review your proposal. Redirecting to your bids page...
              </p>
            </div>
          </div>
        )}

        {/* Property Info */}
        {property && (
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6 mb-8">
            <h3 className="text-lg font-bold text-[#B87333] mb-4">Property Details</h3>
            <div className="grid md:grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-[#676767]">Price:</span>
                <span className="ml-2 text-[#FFD700] font-bold text-xl">
                  ${property.price.toLocaleString()}
                </span>
              </div>
              <div>
                <span className="text-[#676767]">Location:</span>
                <span className="ml-2 text-[#d8c68e]">
                  {property.city}, {property.state}
                </span>
              </div>
              <div>
                <span className="text-[#676767]">Type:</span>
                <span className="ml-2 text-[#d8c68e] capitalize">
                  {property.property_type}
                </span>
              </div>
              <div>
                <span className="text-[#676767]">Transaction:</span>
                <span className="ml-2 text-[#d8c68e] capitalize">
                  {property.transaction_type}
                </span>
              </div>
            </div>
          </div>
        )}

        {/* Proposal Form */}
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <h3 className="text-2xl font-bold text-[#B87333] mb-6 flex items-center gap-2">
              <DollarSign className="w-6 h-6" />
              Your Offer
            </h3>

            {/* Bid Amount */}
            <div className="mb-6">
              <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                Proposal Amount (USD) *
              </label>
              <input
                required
                type="number"
                value={bidAmount}
                onChange={(e) => setBidAmount(e.target.value)}
                step="1000"
                min="0"
                placeholder="Enter your offer"
                className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] text-2xl font-bold placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
              />
              {property && bidAmount && (
                <p className="mt-2 text-sm text-[#676767]">
                  {parseFloat(bidAmount) < property.price ? (
                    <span className="text-yellow-500">
                      ÔÜá´©Å Your offer is {((1 - parseFloat(bidAmount) / property.price) * 100).toFixed(1)}% below asking price
                    </span>
                  ) : parseFloat(bidAmount) > property.price ? (
                    <span className="text-green-500">
                      Ô£ô Your offer is {((parseFloat(bidAmount) / property.price - 1) * 100).toFixed(1)}% above asking price
                    </span>
                  ) : (
                    <span className="text-[#B87333]">Ô£ô Offering asking price</span>
                  )}
                </p>
              )}
            </div>

            {/* Financing Option */}
            <div className="mb-6">
              <label className="flex items-center gap-3 cursor-pointer">
                <input
                  type="checkbox"
                  checked={useFinancing}
                  onChange={(e) => setUseFinancing(e.target.checked)}
                  className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333]"
                />
                <span className="text-[#d8c68e] font-semibold">
                  I plan to use financing
                </span>
              </label>

              {useFinancing && (
                <div className="mt-4">
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Down Payment (USD)
                  </label>
                  <input
                    type="number"
                    value={downPayment}
                    onChange={(e) => setDownPayment(e.target.value)}
                    step="1000"
                    min="0"
                    placeholder="Enter down payment amount"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                  />
                  {downPayment && bidAmount && (
                    <p className="mt-2 text-sm text-[#676767]">
                      Down payment: {((parseFloat(downPayment) / parseFloat(bidAmount)) * 100).toFixed(1)}% of offer
                    </p>
                  )}
                </div>
              )}
            </div>

            {/* Message to Seller */}
            <div>
              <label className="block text-sm font-semibold text-[#d8c68e] mb-2 flex items-center gap-2">
                <FileText className="w-4 h-4" />
                Message to Property Owner (Optional)
              </label>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                rows={5}
                placeholder="Introduce yourself, explain your interest, timeline, etc..."
                className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
              />
            </div>
          </div>

          {/* Terms */}
          <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6">
            <label className="flex items-start gap-3 cursor-pointer">
              <input
                required
                type="checkbox"
                checked={acceptTerms}
                onChange={(e) => setAcceptTerms(e.target.checked)}
                className="w-5 h-5 rounded border-[#2a2a1a] bg-[#0a0a0a] text-[#B87333] focus:ring-[#B87333] mt-1"
              />
              <div className="text-sm text-[#d8c68e]">
                I understand that this is a binding offer. By submitting this proposal, I agree to proceed with the purchase 
                if the property owner accepts my offer. I have completed the property visit and verified all information. *
              </div>
            </label>
          </div>

          {/* Submit */}
          <div className="flex gap-4">
            <button
              type="submit"
              disabled={loading || success}
              className="flex-1 bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold py-4 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 text-lg"
            >
              {loading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  Submitting...
                </>
              ) : success ? (
                <>
                  <Check className="w-5 h-5" />
                  Submitted!
                </>
              ) : (
                <>
                  <TrendingUp className="w-5 h-5" />
                  Submit Proposal
                </>
              )}
            </button>
            <button
              type="button"
              onClick={() => router.back()}
              className="px-8 py-4 border-2 border-[#2a2a1a] hover:border-[#B87333] text-[#d8c68e] font-semibold rounded-lg transition"
            >
              Cancel
            </button>
          </div>
        </form>
      </div>
    </main>
  );
}

export default function ProposalPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#1a1a1a] to-[#0a0a0a] flex items-center justify-center">
        <div className="text-[#d8c68e] text-xl">Loading...</div>
      </div>
    }>
      <ProposalContent />
    </Suspense>
  );
}

"use client";

import { useState, useEffect } from "react";
import { createBrowserSupabaseClient } from "@/lib/supabaseBrowser";
import { 
  Building2, Home, Trees, Waves, MapPin, BedDouble, 
  Bath, Car, Ruler, DollarSign, Filter, X, Search,
  Heart, Phone, Mail, ChevronDown, SlidersHorizontal
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { PropertyCard } from "@publimicro/ui";

// Property type configurations
const PROPERTY_TYPES = [
  { value: 'all', label: 'All Properties', icon: Building2, description: '' },
  { value: 'apartment', label: 'Apartment', icon: Building2, description: 'City apartments and flats' },
  { value: 'house', label: 'House', icon: Home, description: 'Single-family homes' },
  { value: 'chacara', label: 'Ch├ícara', icon: Trees, description: 'Small rural property (<2ha, near cities)' },
  { value: 'sitio', label: 'S├¡tio', icon: Trees, description: 'Medium farm (2-50 hectares)' },
  { value: 'fazenda', label: 'Fazenda', icon: Trees, description: 'Large farm (50+ hectares)' },
  { value: 'rancho', label: 'Rancho', icon: Waves, description: 'Property near water (2+ hectares)' },
  { value: 'commercial', label: 'Commercial', icon: Building2, description: 'Offices, stores, warehouses' },
  { value: 'land', label: 'Land', icon: MapPin, description: 'Empty lots and land' },
];

const TRANSACTION_TYPES = [
  { value: 'all', label: 'All Transactions' },
  { value: 'sale', label: 'For Sale' },
  { value: 'rent', label: 'For Rent' },
  { value: 'lease', label: 'For Lease' },
  { value: 'auction', label: 'Auction' },
];

interface Property {
  id: string;
  title: string;
  description: string;
  property_type: string;
  transaction_type: string;
  price: number;
  bedrooms: number;
  bathrooms: number;
  parking_spaces: number;
  total_area: number;
  city: string;
  state: string;
  country: string;
  slug: string;
  featured: boolean;
  property_photos: { url: string; is_cover: boolean }[];
}

export default function SearchPage() {
  const supabase = createBrowserSupabaseClient();
  const [properties, setProperties] = useState<Property[]>([]);
  const [loading, setLoading] = useState(true);
  const [showFilters, setShowFilters] = useState(false);

  // Filter states
  const [propertyType, setPropertyType] = useState('all');
  const [transactionType, setTransactionType] = useState('all');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const [minBedrooms, setMinBedrooms] = useState('');
  const [minBathrooms, setMinBathrooms] = useState('');
  const [minArea, setMinArea] = useState('');
  const [maxArea, setMaxArea] = useState('');
  const [city, setCity] = useState('');
  const [state, setState] = useState('');

  // Fetch properties
  useEffect(() => {
    fetchProperties();
  }, [propertyType, transactionType]);

  const fetchProperties = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('properties')
        .select(`
          *,
          property_photos(url, is_cover)
        `)
        .eq('status', 'active')
        .not('published_at', 'is', null)
        .order('featured', { ascending: false })
        .order('created_at', { ascending: false });

      // Apply filters
      if (propertyType !== 'all') {
        query = query.eq('property_type', propertyType);
      }
      if (transactionType !== 'all') {
        query = query.eq('transaction_type', transactionType);
      }
      if (minPrice) {
        query = query.gte('price', parseFloat(minPrice));
      }
      if (maxPrice) {
        query = query.lte('price', parseFloat(maxPrice));
      }
      if (minBedrooms) {
        query = query.gte('bedrooms', parseInt(minBedrooms));
      }
      if (minBathrooms) {
        query = query.gte('bathrooms', parseInt(minBathrooms));
      }
      if (minArea) {
        query = query.gte('total_area', parseFloat(minArea));
      }
      if (maxArea) {
        query = query.lte('total_area', parseFloat(maxArea));
      }
      if (city) {
        query = query.ilike('city', `%${city}%`);
      }
      if (state) {
        query = query.ilike('state', `%${state}%`);
      }

      const { data, error } = await query;

      if (error) throw error;
      setProperties(data || []);
    } catch (error) {
      console.error('Error fetching properties:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = () => {
    fetchProperties();
  };

  const clearFilters = () => {
    setPropertyType('all');
    setTransactionType('all');
    setMinPrice('');
    setMaxPrice('');
    setMinBedrooms('');
    setMinBathrooms('');
    setMinArea('');
    setMaxArea('');
    setCity('');
    setState('');
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
    }).format(price);
  };

  const getPropertyTypeIcon = (type: string) => {
    const config = PROPERTY_TYPES.find(t => t.value === type);
    return config ? config.icon : Building2;
  };

  const getCoverPhoto = (photos: Array<{ is_cover?: boolean; url?: string }>) => {
    const cover = photos?.find(p => p.is_cover);
    return cover?.url || photos?.[0]?.url || '/images/placeholder-property.jpg';
  };

  return (
    <main className="min-h-screen bg-gradient-to-b from-[#0a0a0a] via-[#0d0d0d] to-[#0a0a0a]">
      <div className="max-w-[1920px] mx-auto px-4 sm:px-6 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-[#B87333] via-[#DAA520] to-[#FFD700] bg-clip-text text-transparent mb-3">
            Search Properties
          </h1>
          <p className="text-[#d8c68e] text-lg">
            Find your perfect property from our extensive listings
          </p>
        </div>

        <div className="grid lg:grid-cols-4 gap-8">
          {/* Filters Sidebar */}
          <div className="lg:col-span-1">
            <div className="bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] border-2 border-[#2a2a1a] rounded-2xl p-6 sticky top-24">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-[#B87333] flex items-center gap-2">
                  <SlidersHorizontal className="w-5 h-5" />
                  Filters
                </h2>
                <button
                  onClick={clearFilters}
                  className="text-sm text-[#676767] hover:text-[#B87333] transition flex items-center gap-1"
                >
                  <X className="w-4 h-4" />
                  Clear
                </button>
              </div>

              <div className="space-y-6">
                {/* Property Type */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Property Type
                  </label>
                  <select
                    value={propertyType}
                    onChange={(e) => setPropertyType(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    {PROPERTY_TYPES.map(type => (
                      <option key={type.value} value={type.value}>
                        {type.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Transaction Type */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Transaction
                  </label>
                  <select
                    value={transactionType}
                    onChange={(e) => setTransactionType(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    {TRANSACTION_TYPES.map(type => (
                      <option key={type.value} value={type.value}>
                        {type.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Location */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    City
                  </label>
                  <input
                    type="text"
                    value={city}
                    onChange={(e) => setCity(e.target.value)}
                    placeholder="Enter city name"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    State/Region
                  </label>
                  <input
                    type="text"
                    value={state}
                    onChange={(e) => setState(e.target.value)}
                    placeholder="Enter state"
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                  />
                </div>

                {/* Price Range */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Price Range
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      type="number"
                      value={minPrice}
                      onChange={(e) => setMinPrice(e.target.value)}
                      placeholder="Min"
                      className="bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-3 py-2 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                    />
                    <input
                      type="number"
                      value={maxPrice}
                      onChange={(e) => setMaxPrice(e.target.value)}
                      placeholder="Max"
                      className="bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-3 py-2 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                    />
                  </div>
                </div>

                {/* Bedrooms */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Min. Bedrooms
                  </label>
                  <select
                    value={minBedrooms}
                    onChange={(e) => setMinBedrooms(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    <option value="">Any</option>
                    <option value="1">1+</option>
                    <option value="2">2+</option>
                    <option value="3">3+</option>
                    <option value="4">4+</option>
                    <option value="5">5+</option>
                  </select>
                </div>

                {/* Bathrooms */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Min. Bathrooms
                  </label>
                  <select
                    value={minBathrooms}
                    onChange={(e) => setMinBathrooms(e.target.value)}
                    className="w-full bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-4 py-3 text-[#e6c86b] focus:border-[#B87333] focus:outline-none"
                  >
                    <option value="">Any</option>
                    <option value="1">1+</option>
                    <option value="2">2+</option>
                    <option value="3">3+</option>
                    <option value="4">4+</option>
                  </select>
                </div>

                {/* Area */}
                <div>
                  <label className="block text-sm font-semibold text-[#d8c68e] mb-2">
                    Area (m┬▓ or hectares)
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      type="number"
                      value={minArea}
                      onChange={(e) => setMinArea(e.target.value)}
                      placeholder="Min"
                      className="bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-3 py-2 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                    />
                    <input
                      type="number"
                      value={maxArea}
                      onChange={(e) => setMaxArea(e.target.value)}
                      placeholder="Max"
                      className="bg-[#0a0a0a] border border-[#2a2a1a] rounded-lg px-3 py-2 text-[#e6c86b] placeholder-[#676767] focus:border-[#B87333] focus:outline-none"
                    />
                  </div>
                </div>

                {/* Search Button */}
                <button
                  onClick={handleSearch}
                  className="w-full bg-gradient-to-r from-[#B87333] to-[#DAA520] hover:from-[#DAA520] hover:to-[#FFD700] text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
                >
                  <Search className="w-5 h-5" />
                  Search
                </button>
              </div>
            </div>
          </div>

          {/* Results Grid */}
          <div className="lg:col-span-3">
            {loading ? (
              <div className="text-center py-20">
                <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-[#B87333] border-t-transparent"></div>
                <p className="mt-4 text-[#d8c68e]">Loading properties...</p>
              </div>
            ) : properties.length === 0 ? (
              <div className="text-center py-20">
                <Building2 className="w-16 h-16 text-[#676767] mx-auto mb-4" />
                <h3 className="text-2xl font-bold text-[#d8c68e] mb-2">No properties found</h3>
                <p className="text-[#676767] mb-6">Try adjusting your filters</p>
                <button
                  onClick={clearFilters}
                  className="px-6 py-3 bg-[#B87333] hover:bg-[#DAA520] text-white font-semibold rounded-lg transition"
                >
                  Clear Filters
                </button>
              </div>
            ) : (
              <>
                <div className="flex items-center justify-between mb-6">
                  <p className="text-[#d8c68e]">
                    <span className="font-bold text-[#B87333]">{properties.length}</span> properties found
                  </p>
                </div>

                <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-6">
                  {properties.map((property) => (
                    <PropertyCard
                      key={property.id}
                      id={property.id}
                      title={property.title}
                      description={property.description}
                      price={property.price}
                      featured={property.featured}
                      location={{
                        city: property.city,
                        state: property.state,
                        neighborhood: undefined
                      }}
                      area={{
                        total: property.total_area || 0
                      }}
                      features={{
                        bedrooms: property.bedrooms,
                        bathrooms: property.bathrooms,
                        parking: property.parking_spaces
                      }}
                      photos={property.property_photos?.map(p => p.url) || []}
                      link={`/property/${property.slug}`}
                      type="property"
                    />
                  ))}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
